    s.push(`<linearGradient id="c4-rai" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#FFF0C0" stop-opacity=".95"/><stop offset=".4" stop-color="#FFE29A" stop-opacity=".45"/><stop offset="1" stop-color="#FFD98A" stop-opacity=".12"/></linearGradient>`);
