    s.push(`<linearGradient id="c4-riv" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#9A5A2C"/><stop offset=".3" stop-color="#C4844C"/><stop offset=".52" stop-color="#E8B07A"/><stop offset=".74" stop-color="#C4844C"/><stop offset="1" stop-color="#9A5A2C"/></linearGradient>`);
    s.push(`<linearGradient id="c4-or" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#FFF4C0"/><stop offset=".35" stop-color="#F4C84A"/><stop offset=".7" stop-color="#C8921E"/><stop offset="1" stop-color="#8A5A10"/></linearGradient>`);
    s.push(`<linearGradient id="c4-verre" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#E8FAFF" stop-opacity=".55"/><stop offset=".45" stop-color="#9AD8F0" stop-opacity=".18"/><stop offset="1" stop-color="#CFF2FF" stop-opacity=".42"/></linearGradient>`);
    s.push(`<radialGradient id="c4-ver" cx=".5" cy=".1" r=".9"><stop offset="0" stop-color="#FFFFFF"/><stop offset=".45" stop-color="#FFF6D4"/><stop offset="1" stop-color="#F8DC94"/></radialGradient>`);
    s.push(`<radialGradient id="c4-vig" cx=".5" cy=".46" r=".72"><stop offset=".5" stop-color="#2A1208" stop-opacity="0"/><stop offset=".85" stop-color="#2A1208" stop-opacity=".32"/><stop offset="1" stop-color="#2A1208" stop-opacity=".6"/></radialGradient>`);
