    s.push(`<path d="${bande(190, 10, 0)}" fill="#D8EBA0"/><path d="${bande(330, 14, 1.4)}" fill="#A8DE8C"/><path d="${bande(500, 16, 2.6)}" fill="#7FCB94"/><path d="${bande(640, 12, .7)}" fill="#5FAE86"/>`);
