    // ---- 4. la rivière : du bassin, sous le pont et le croisement, en S jusqu'au premier plan (la colonne vertébrale)
    const RIV = lisse([[CX, 292], [CX, 340], [CX, 400], [536, 452], [528, 496], [572, 548], [600, 592], [570, 640], [596, 690], [650, 748]], 4), HWR = RIV.map((p, i) => 36 + Math.pow(i / (RIV.length - 1), 1.5) * 56);
