    s.push(`<path d="${chemin(RIV)}" fill="none" stroke="#E8B07A" stroke-width="18" opacity=".35" stroke-linecap="round"/>`);

    // le grand tuyau de verre de la boucle droite passe SOUS la piste pour monter à la voûte
