    const TUY = `M${MARE[0]} ${MARE[1] - 2}C${MARE[0]} 360 ${MARE[0] + 76} 330 ${MARE[0] + 80} 250S${MARE[0] + 84} 140 ${MARE[0] + 84} -10`;
