    for (let i = 8; i < RIV.length - 4; i += 9) { const p = RIV[i], q = RIV[i + 2], dx = q[0] - p[0], dy = q[1] - p[1], l = Math.hypot(dx, dy) || 1, nx = -dy / l, ny = dx / l, w = HWR[i] * .55, o = ((i / 9) % 2 ? .3 : -.3) * HWR[i];
      s.push(`<path d="M${f(p[0] + nx * (o - w * .5))} ${f(p[1] + ny * (o - w * .5))}q${f(nx * w * .5 + dx / l * 6)} ${f(ny * w * .5 + dy / l * 6)} ${f(nx * w)} ${f(ny * w)}" stroke="#FFE8C0" stroke-width="2.4" fill="none" stroke-linecap="round" opacity=".75"/>`); }
    // ---- 5. la piste : chocolat noir bordé de crème (plus sombre que la rivière) ; un seul pont en sucre d'orge
