      SU.forEach(([dx, dy, R]) => s.push(`<path d="M${x + 4} ${y1 + 10}Q${f(x + dx * .4)} ${f(y1 + dy * .2)} ${f(x + dx)} ${f(y1 + dy)}" stroke="#FFF6EC" stroke-width="6" fill="none" stroke-linecap="round"/><path d="M${x + 4} ${y1 + 10}Q${f(x + dx * .4)} ${f(y1 + dy * .2)} ${f(x + dx)} ${f(y1 + dy)}" stroke="#2A1208" stroke-width="1" fill="none" opacity=".5"/>`));
